var curry = function(fn) {
    // `collected` is never mutated: each call builds a *new* array and a new
    // closure over it, so two calls on the same partial can't see each other's args.
    var gather = function(collected) {
        return function() {
            var args = collected.concat(Array.prototype.slice.call(arguments));
            return args.length >= fn.length ? fn.apply(this, args) : gather(args);
        };
    };
    return gather([]);
};

