var curry = function(fn) {
    // A bound function remembers its leading arguments, and its `length` is the
    // target's length minus how many it has bound (never below 0). So "how many
    // arguments are still missing" is just `next.length`.
    var step = function(bound) {
        return function() {
            var next = bound.bind.apply(bound, [null].concat(Array.prototype.slice.call(arguments)));
            return next.length === 0 ? next() : step(next);
        };
    };
    return step(fn);
};

